SELECT DISTINCT ?item ?matchedLabel ?en ?zh ?description ?kind WHERE {
          VALUES ?matchedLabel { "Cauchy sequence"@en "Dirac delta"@en "Fourier series"@en "Fourier transform"@en "Green's function"@en "Green's theorem"@en "Hessian"@en "Jacobian"@en "Laplace transform"@en "Lebesgue integral"@en "Lipschitz continuity"@en "Maclaurin series"@en "Riemann integral"@en "Rolle's theorem"@en "Stokes' theorem"@en "Taylor expansion"@en "Taylor series"@en "absolute convergence"@en "antiderivative"@en "boundary"@en "boundary value problem"@en "bounded sequence"@en "cauchy sequence"@en "chain rule"@en "change of variables"@en "characteristic equation"@en "closed set"@en "closure"@en "compact set"@en "compactness"@en "conditional convergence"@en "continuity"@en "definite integral"@en "dense set"@en "derivative"@en "differentiable"@en "differentiation"@en "dirac delta"@en "directional derivative"@en "discontinuity"@en "distribution"@en "divergence"@en "divergence theorem"@en "double integral"@en "fourier series"@en "fourier transform"@en "fundamental theorem of calculus"@en "general solution"@en "gradient"@en "green's function"@en "green's theorem"@en "hessian"@en "homogeneous equation"@en "improper integral"@en "indefinite integral"@en "inhomogeneous equation"@en "initial value problem"@en "integral"@en "integration by parts"@en "interior"@en "jacobian"@en "laplace transform"@en "lebesgue integral"@en "limit inferior"@en "limit superior"@en "line integral"@en "lipschitz continuity"@en "maclaurin series"@en "mean value theorem"@en "metric"@en "metric space"@en "monotone sequence"@en "neighborhood"@en "open set"@en "ordinary differential equation"@en "partial derivative"@en "partial differential equation"@en "particular solution"@en "pointwise convergence"@en "power series"@en "product rule"@en "quotient rule"@en "radius of convergence"@en "remainder"@en "riemann integral"@en "rolle's theorem"@en "separation of variables"@en "series"@en "stokes' theorem"@en "surface integral"@en "taylor expansion"@en "taylor series"@en "triple integral"@en "unifo